{
  "findings": [
    {
      "check_id": "CKV_AWS_40",
      "title": "Ensure IAM policies are attached only to groups or roles",
      "resource": "aws_iam_user_policy_attachment.privesc18-PassExistingRoleToNewGlueDevEndpoint-user-attach-policy",
      "severity": "MEDIUM",
      "explanation": "Attaching IAM policies directly to users increases the complexity of access management and the risk of excessive privileges. Policies should be attached to groups or roles instead."
    }
  ],
  "patched_code": "resource "aws_iam_group" "privesc18-PassExistingRoleToNewGlueDevEndpoint-group" {
  name = "privesc18-PassExistingRoleToNewGlueDevEndpoint-group"
}

resource "aws_iam_group_policy_attachment" "privesc18-PassExistingRoleToNewGlueDevEndpoint-group-attach-policy" {
  group      = aws_iam_group.privesc18-PassExistingRoleToNewGlueDevEndpoint-group.name
  policy_arn = aws_iam_policy.privesc18-PassExistingRoleToNewGlueDevEndpoint.arn
}

resource "aws_iam_user_group_membership" "privesc18-PassExistingRoleToNewGlueDevEndpoint-user-group-membership" {
  user = aws_iam_user.privesc18-PassExistingRoleToNewGlueDevEndpoint-user.name
  groups = [
    aws_iam_group.privesc18-PassExistingRoleToNewGlueDevEndpoint-group.name
  ]
}",
  "fix_summary": "Replaced the direct attachment of the IAM policy to the user with a group-based approach. Created an IAM group, attached the policy to the group, and added the user to the group to maintain the same permissions while improving security."
}
